const $=s=>document.querySelector(s);const img=(id,w=500)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=80`;const categories=[['Fresh','Fruits & vegetables','photo-1542838132-92c53300491e'],['Breakfast','Dairy & eggs','🥛'],['Breakfast','Bread & bakery','🍞'],['Snacks','Snacks & munchies','🍿'],['Snacks','Drinks & sips','🧃'],['Home','Personal care','🧴'],['Home','Home essentials','🧼'],['Home','Pet favourites','🐾']];const products=[{id:1,name:'Sweet ripe bananas',cat:'Fresh',qty:'6 pcs',price:48,photo:'photo-1571771894821-ce9b6c11b08e',badge:'FRESH PICK'},{id:2,name:'Fresh whole milk',cat:'Breakfast',qty:'500 ml',price:30,emoji:'🥛',badge:'DAILY ESSENTIAL'},{id:3,name:'Whole wheat bread',cat:'Breakfast',qty:'400 g',price:45,emoji:'🍞'},{id:4,name:'Farm fresh eggs',cat:'Breakfast',qty:'6 pcs',price:60,emoji:'🥚'},{id:5,name:'Juicy red tomatoes',cat:'Fresh',qty:'500 g',price:25,photo:'photo-1546094096-0df4bcaaa337'},{id:6,name:'Classic salted popcorn',cat:'Snacks',qty:'100 g',price:65,emoji:'🍿'},{id:7,name:'Fresh orange juice',cat:'Snacks',qty:'1 litre',price:110,emoji:'🧃'},{id:8,name:'Gentle hand wash',cat:'Home',qty:'250 ml',price:85,emoji:'🧴'},{id:9,name:'Everyday cleaning spray',cat:'Home',qty:'500 ml',price:120,emoji:'🧼'}];let cart={};try{cart=JSON.parse(localStorage.getItem('dropbell-cart')||'{}');if(!cart||Array.isArray(cart)||typeof cart!=='object')cart={};for(const id in cart)if(!products.some(p=>p.id==id)||!Number.isInteger(cart[id])||cart[id]<1||cart[id]>99)delete cart[id]}catch{}let filter='All';let timer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('visible'),2200)}function stepper(p){return cart[p.id]?`<div class="stepper" aria-label="Quantity for ${p.name}"><button data-id="${p.id}" data-delta="-1" aria-label="Remove one ${p.name}">−</button><span>${cart[p.id]}</span><button data-id="${p.id}" data-delta="1" aria-label="Add one ${p.name}">+</button></div>`:`<button class="add" data-id="${p.id}" data-delta="1" aria-label="Add ${p.name} to bag">ADD +</button>`}function render(){const query=$('#search').value.toLowerCase().trim();let list=products.filter(p=>(filter==='All'||p.cat===filter)&&`${p.name} ${p.cat}`.toLowerCase().includes(query));if(filter==='All'&&!query)list=list.slice(0,5);$('#productGrid').innerHTML=list.map(p=>`<article class="product"><div class="product-photo">${p.photo?`<img src="${img(p.photo)}" alt="${p.name}" loading="lazy">`:`<span class="emoji" role="img" aria-label="${p.name}">${p.emoji}</span>`}${p.badge?`<span class="badge">${p.badge}</span>`:''}</div><div class="product-body"><small>${p.cat==='Fresh'?'Fruits & vegetables':p.cat==='Breakfast'?'Dairy & breakfast':p.cat==='Home'?'Home essentials':'Snacks & drinks'}</small><h3>${p.name}</h3><p class="quantity">${p.qty}</p><div class="product-bottom"><strong>₹${p.price}</strong>${stepper(p)}</div></div></article>`).join('');$('#empty').hidden=!!list.length;$('#count').textContent=Object.values(cart).reduce((a,b)=>a+b,0);document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter))});renderCart()}function renderCart(){const entries=products.filter(p=>cart[p.id]);$('#cartItems').innerHTML=entries.length?entries.map(p=>`<div class="cart-row"><div><b>${p.name}</b><p>${p.qty} · ₹${p.price}</p></div>${stepper(p)}</div>`).join(''):'<p>Your bag is waiting for something good. Add a few favourites to get started.</p>';$('#cartSummary').innerHTML=entries.length?`<div class="total"><span>Subtotal</span><span>₹${entries.reduce((a,p)=>a+p.price*cart[p.id],0)}</span></div><p>Delivery fees calculated during checkout.</p>`:''}$('#categoryGrid').innerHTML=categories.map(([cat,name,photo])=>`<button class="category" data-filter="${cat}" aria-label="Shop ${name}"><div class="category-photo">${photo.startsWith('photo')?`<img src="${img(photo,300)}" alt="" loading="lazy">`:`<span aria-hidden="true">${photo}</span>`}</div>${name}</button>`).join('');document.addEventListener('click',e=>{const change=e.target.closest('[data-delta]');if(change){const id=Number(change.dataset.id);cart[id]=Math.min(99,Math.max(0,(cart[id]||0)+Number(change.dataset.delta)));if(!cart[id])delete cart[id];try{localStorage.setItem('dropbell-cart',JSON.stringify(cart))}catch{}render();return}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;$('#search').value='';render();$('#products').scrollIntoView({behavior:'smooth'});}const close=e.target.closest('[data-close]');if(close)document.getElementById(close.dataset.close).close()});$('#search').addEventListener('input',render);document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#search').focus()}});$('#shop').onclick=()=>$('#categories').scrollIntoView({behavior:'smooth'});$('#allCategories').onclick=()=>{filter='All';$('#search').value='';render();$('#products').scrollIntoView({behavior:'smooth'})};$('#cartButton').onclick=()=>$('#cartDialog').showModal();$('#location').onclick=()=>$('#locationDialog').showModal();try{const area=localStorage.getItem('dropbell-area');if(area)$('#locationLabel').textContent=area+' ⌄'}catch{}$('#locationForm').onsubmit=e=>{e.preventDefault();const area=$('#area').value.trim();if(!area)return;$('#locationLabel').textContent=area+' ⌄';try{localStorage.setItem('dropbell-area',area)}catch{}$('#locationDialog').close();toast('Delivery location saved')};for(const [id,title,text]of [['help','Here to help','This is a Dropbell shopping experience preview. Support and order tracking will be available when the service launches.'],['about','Good things, closer home.','Dropbell brings groceries and everyday goods to your doorstep. This homepage is an interactive design prototype with sample inventory.']])$('#'+id).onclick=()=>{$('#infoTitle').textContent=title;$('#infoText').textContent=text;$('#infoDialog').showModal()};document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));render();
